#include "TestCommon.h"
#include "Interleave.h"
int main(int argc,char**argv){using namespace gpuls;try{require(argc==3,"G64CodecAudit inputs output");auto refs=cases(argv[1]);unsigned passed=0;for(unsigned count:{1u,31u,32u,33u,63u,64u,65u,99u,100u,101u,511u,512u,513u,2839u}){Pack p(count);for(unsigned i=0;i<count;i++)p.system(i,*refs[(i*17+count)%refs.size()]->w);for(unsigned mode:{1u,2u}){Wire w(p,mode);std::vector<bool> inputUsed(w.input.size(),false),workUsed(w.workBytes,false),canonicalNumeric(p.bytes.size(),false);std::vector<char>seed(p.scratchBytes);for(size_t j=0;j<seed.size()/8;j++){uint64_t tag=uint64_t(j)*0x9e3779b97f4a7c15ull+0x123456789abcdef0ull;std::memcpy(seed.data()+j*8,&tag,8);}auto encoded=w.encodeWork(seed);for(unsigned id=0;id<count;id++){auto&m=p.systems[id];Meta actual;std::memcpy(&actual,w.input.data()+id*64,64);Meta expected=m;expected.pad0=actual.pad0;require(std::memcmp(&actual,&expected,64)==0,"Actual encoded metadata changed");require(actual.pad0+sizeof(Tile)<=w.input.size(),"Descriptor bounds");Tile tile;std::memcpy(&tile,w.input.data()+actual.pad0,sizeof(tile));require(std::memcmp(&tile,&w.tiles[id/32],sizeof(Tile))==0,"Actual descriptor wrong");for(auto&s:w.maps[id].input)for(unsigned k=0;k<s.count;k++){uint32_t address=mode==2?Wire::physical(tile.inputBase,s.plane+k*8,id%32):s.canonical+k*8;require(address%8==0&&uint64_t(address)+8<=w.input.size(),"Input bit pair bounds/alignment");for(unsigned b=0;b<8;b++){require(!inputUsed[address+b],"Input numerical alias");inputUsed[address+b]=true;canonicalNumeric[s.canonical+k*8+b]=true;}require(std::memcmp(w.input.data()+address,p.bytes.data()+s.canonical+k*8,8)==0,"Actual encoded input bits differ");}for(auto&s:w.maps[id].work)for(unsigned k=0;k<s.count;k++){uint32_t address=Wire::physical(tile.workBase,s.plane+k*8,id%32);require(address%8==0&&uint64_t(address)+8<=encoded.size(),"Work bit pair bounds/alignment");for(unsigned b=0;b<8;b++){require(!workUsed[address+b],"Work numerical alias");workUsed[address+b]=true;}require(std::memcmp(encoded.data()+address,seed.data()+s.canonical+k*8,8)==0,"Unique work tag differs");}uint32_t st=tile.statusBase+(id%32)*32;for(unsigned b=0;b<32;b++){require(!workUsed[st+b],"Integer status aliases numeric data");workUsed[st+b]=true;}require(std::memcmp(encoded.data()+st,seed.data()+m.statusOffset,32)==0,"Status byte mapping");}
 for(size_t b=0;b<p.bytes.size();b++){bool headerPad=b<count*64&&b%64>=56&&b%64<60;if(!headerPad&&!(mode==2&&canonicalNumeric[b]))require(w.input[b]==p.bytes[b],"Integer metadata representation changed");}passed++;}}
 text(fs::path(argv[2])/"metadata-alias-audit.json","{\"passed\":"+std::to_string(passed)+",\"checks\":\"actual wire metadata/descriptors, every numeric bit pair, unique physical addresses, status separation, integer bytes, unique work tags\"}");return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
